Generating <pre><code>Flux.generate(sink -&gt; sink.next(42));

Flux.generate(
    () -&gt; 0,                                 // state supplier
    (state, sink) -&gt; {
        sink.next(state);
        if (state == 10) sink.complete();
        return state + 1;
